import{_ as t,o as i,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Security Policy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security-policy.md","filePath":"guide/security-policy.md"}'),a={name:"guide/security-policy.md"};function s(l,e,n,c,u,d){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="security-policy" tabindex="-1">Security Policy <a class="header-anchor" href="#security-policy" aria-label="Permalink to &quot;Security Policy&quot;">​</a></h1><p>We take the security of our billing and automation platform seriously. This document outlines how to report vulnerabilities and our commitment to resolving them.</p><hr><h2 id="🛡️-reporting-a-vulnerability" tabindex="-1">🛡️ Reporting a Vulnerability <a class="header-anchor" href="#🛡️-reporting-a-vulnerability" aria-label="Permalink to &quot;🛡️ Reporting a Vulnerability&quot;">​</a></h2><p>If you discover a security vulnerability within FOSSBilling, please <strong>do not open a public issue</strong>. Instead, follow these steps:</p><ol><li><strong>Email:</strong> Send a detailed report to <code>security@fossbilling.org</code>.</li><li><strong>Details:</strong> Include a proof-of-concept (PoC), steps to reproduce, and the potential impact.</li><li><strong>Response:</strong> Our core team will acknowledge your report within 48 hours.</li></ol><hr><h2 id="🔒-security-lifecycle" tabindex="-1">🔒 Security Lifecycle <a class="header-anchor" href="#🔒-security-lifecycle" aria-label="Permalink to &quot;🔒 Security Lifecycle&quot;">​</a></h2><ul><li><strong>Coordinated Disclosure:</strong> We ask that you give us reasonable time to investigate and patch the issue before making any public disclosure.</li><li><strong>Patches:</strong> We aim to release a security patch within 14 days for critical vulnerabilities.</li><li><strong>Advisories:</strong> Once a patch is released, we will publish a GitHub Security Advisory (GHSA) to notify the community.</li></ul><hr><h2 id="🛑-out-of-scope" tabindex="-1">🛑 Out of Scope <a class="header-anchor" href="#🛑-out-of-scope" aria-label="Permalink to &quot;🛑 Out of Scope&quot;">​</a></h2><p>The following are generally considered out of scope for security reports:</p><ul><li>Brute-force attacks (ensure you have rate limiting enabled).</li><li>Attacks requiring physical access to the server.</li><li>Spam reports (unless it bypasses the Anti-Spam module filters).</li><li>Issues in third-party extensions not maintained by the core team.</li></ul><hr><h2 id="🛠️-security-hardening" tabindex="-1">🛠️ Security Hardening <a class="header-anchor" href="#🛠️-security-hardening" aria-label="Permalink to &quot;🛠️ Security Hardening&quot;">​</a></h2><p>For production environments, always follow these best practices:</p><ol><li><strong>Change the <code>JWT_SECRET</code>:</strong> Never use the default key provided in <code>.env.example</code>.</li><li><strong>Use HTTPS:</strong> Ensure all traffic between your portals and the API is encrypted.</li><li><strong>DB Access:</strong> Restrict PostgreSQL access to the API container IP only.</li><li><strong>Regular Updates:</strong> Keep your Docker images updated to the latest minor version.</li></ol>',17)])])}const y=t(a,[["render",s]]);export{h as __pageData,y as default};
